    #if defined( USE_LOGARITHMIC_DEPTH_BUFFER )
	uniform float logDepthBufFC;
	varying float vFragDepth;
	varying float vIsPerspective;
#endif

    uniform vec3 lightPosition;
    uniform sampler2D diffuseMap;
    uniform sampler2D nightMap;
    uniform sampler2D cloudMap;
    uniform float uCloudOpacity;
    uniform sampler2D specularMap;
    uniform sampler2D bumpMap;
    uniform float bumpScale;
    uniform float emission;
    uniform float uNightThreshold;
    uniform float uNightSoftness;
    uniform float uCavityStrength;
    uniform float uTerrainLambert;
    uniform float uTerrainAmbient;
    uniform float uTerrainAmbientSunRef;
    // Радиус тела в единицах сцены: домен средней полосы детали И длина дуги uv
    // в тени облаков, параллаксе и dip облачного слоя — всем нужен БЕЗ гейта USE_TERRAIN_MACRO_DETAIL (тень
    // облаков работает и при macroStrength 0), поэтому объявление живёт здесь,
    // а не в чанке terrainMacroDetailUniforms.
    uniform float uBodyRadiusUnits;
    // Доля окклюзии на ПРЯМОМ свете: 0 — AO/полость не гасят солнце (физика),
    // 1 — прежний вид (окклюзия множила и прямой свет вместе с цветом)
    uniform float uTerrainOcclusionDirect;
    // three не биндит normalMatrix во фрагментник автоматически (только в
    // вершинный пролог) — юниформ общий на программу, объявление здесь просто
    // делает его видимым этому шейдеру.
    uniform mat3 normalMatrix;

    #ifdef USE_LIGHT_TINT
      // Цвет прямого света звезды, linear; амбиент и ночная сторона им не красятся
      uniform vec3 uLightColor;
    #endif

    #ifdef USE_SUN_TINT

  uniform sampler2D uAtmoTransmittance;
  uniform float uAtmoBottomRadius;
  uniform float uAtmoTopRadius;
  uniform float uAtmoSunAngularRadius;
  uniform float uAtmoDatumRadius;
  uniform float uSunTintStrength;
  uniform sampler2D uAtmoIrradiance;
  uniform float uSkyAmbientStrength;

    #endif

    #ifdef USE_GIANT_DETAIL

  uniform float uGiantRadiusKm;
  uniform float uGiantDetailScaleKm;
  uniform float uGiantDetailStretch;
  uniform float uGiantDetailWarp;
  uniform float uGiantDetailTextureWarp;
  uniform float uGiantDetailStrength;
  uniform float uGiantDetailFadeUnits;

    #endif

    varying vec2 vUv;
    varying vec3 vNormal;
    varying vec3 vPosition;
    varying vec3 vViewLightDirection;
    varying vec3 vLocalLightDirection;
    varying vec3 vViewPosition;
    varying vec3 vLocalDir;
    varying vec3 vLocalViewDir;

    #ifdef USE_SLOPE
      // Наклон геометрии средней полосы B — домешивается в декод slope-карты
      varying vec2 vMidTilt;
      uniform float uSlopeRange;

  vec3 perturbNormalFromSlope(vec3 surfNormal, vec3 east, vec2 uv, vec2 extraSlope, out vec2 mapSlopeOut) {
    float len = length(east);
    if (len < 1e-4) {
      mapSlopeOut = vec2(0.0);
      return surfNormal; // полюс: тангенс вырожден
    }

    vec3 T = east / len;
    vec3 B = cross(surfNormal, T);

    vec2 decoded = (texture2D(bumpMap, uv).xy * 255.0 - 128.0) * (uSlopeRange / 127.0);
    // маска зон материала берёт уклон карты без полосы B (см. хост)
    mapSlopeOut = decoded;
    // bumpScale - художественный множитель декода карты; наклон полосы B
    // (extraSlope) честный, входит как есть
    vec2 slope = bumpScale * decoded + extraSlope;

    return normalize(surfNormal - (slope.x * T + slope.y * B));
  }

    #endif

    // Развёртка из направления: рельеф и облачный слой (у легаси-сферы тоже — точка слоя не вершина)
    #if defined(USE_TERRAIN_UV) || defined(USE_CLOUD)

  vec2 terrainUv(vec3 dirLocal) {
    float phi = atan(dirLocal.z, -dirLocal.x);
    float uRaw = phi / 6.28318530717958647692;
    float u1 = fract(uRaw);
    float u2 = fract(uRaw + 0.5) - 0.5;
    float u = fwidth(u1) <= fwidth(u2) ? u1 : u2;

    return vec2(u, 1.0 - acos(clamp(dirLocal.y, -1.0, 1.0)) / 3.14159265358979323846);
  }

    #endif

    // Тень рельефа: гейт вложен в USE_TERRAIN_UV (та же карта высот), читает uBodyRadiusUnits выше
    #ifdef USE_TERRAIN_SHADOW

  uniform sampler2D uShadowHeightMap;
  uniform float uShadowHeightMin;
  uniform float uShadowHeightRange;
  uniform float uShadowTexelAngle;
  uniform float uShadowMaxDistUnits;
  uniform float uShadowPenumbraTan;
  uniform float uTerrainShadowStrength;
  // Ближний слой: плитка высот у камеры (NearShadowTile), тело-локально; вес 0 — плитки нет
  uniform sampler2D uNearTile;
  uniform vec3 uNearTileCenter;
  uniform vec3 uNearTileEast;
  uniform vec3 uNearTileNorth;
  uniform float uNearTileTexelMeters;
  uniform float uNearTileTexels;
  uniform float uNearTileWeight;
  uniform float uNearShadowMaxDistMeters;
  uniform float uBodyRadiusMeters;


  #define TERRAIN_SHADOW_STEPS 20
  // bias = texel · это, высота: склон положе ≈3° тени на себя не кладёт
  #define TERRAIN_SHADOW_BIAS_SLOPE 0.05

  vec2 terrainShadowUv(vec3 dirLocal) {
    float phi = atan(dirLocal.z, -dirLocal.x);
    return vec2(phi / 6.28318530717958647692, acos(clamp(dirLocal.y, -1.0, 1.0)) / 3.14159265358979323846);
  }

  float terrainShadowHeight(vec3 dirLocal) {
    return uShadowHeightMin + texture2D(uShadowHeightMap, terrainShadowUv(dirLocal)).r * uShadowHeightRange;
  }

  // 1 — освещено, 0 — в тени; dir — радиаль фрагмента, sunLocal — единичное НА солнце, система тела.
  // Солнце под горизонтом не пропускается: ночь склону к солнцу даёт только марш
  float terrainShadowMarch(vec3 dir, vec3 sunLocal) {
    float R = uBodyRadiusUnits;
    vec3 p0 = dir * (R + terrainShadowHeight(dir));
    // дуга текселя — первый шаг и смещение: короче неё карта ничего не знает
    float texel = R * uShadowTexelAngle;
    float bias = texel * TERRAIN_SHADOW_BIAS_SLOPE;
    float sMin = texel * 2.0;
    float sMax = max(uShadowMaxDistUnits, sMin * 2.0);
    // геометрический шаг: у подножия важен тексель, в хвосте — десятки км
    float ratio = pow(sMax / sMin, 1.0 / float(TERRAIN_SHADOW_STEPS - 1));
    float s = sMin;
    float occl = 0.0;

    for (int i = 0; i < TERRAIN_SHADOW_STEPS; i++) {
      vec3 p = p0 + sunLocal * s;
      float r = length(p);
      vec3 d = p / r;
      // солнце под горизонтом: луч сразу уходит под грунт — pen > 0, это тень самого тела
      float hRay = r - R;
      // полутень: заглубление луча в долях углового размера солнца на этой дистанции
      float pen = (terrainShadowHeight(d) - hRay - bias) / max(s * uShadowPenumbraTan, 1e-6);
      occl = max(occl, clamp(pen, 0.0, 1.0));
      if (occl >= 1.0) break;
      s *= ratio;
    }

    return 1.0 - occl;
  }


  #define TERRAIN_NEAR_SHADOW_STEPS 16
  #define TERRAIN_NEAR_SHADOW_BIAS_SLOPE 0.05

  // (x, y) = R·(d·E, d·N)/(d·c), метры; d — в полусфере центра плитки
  vec2 terrainNearTileXY(vec3 d) {
    float k = uBodyRadiusMeters / dot(d, uNearTileCenter);
    return vec2(dot(d, uNearTileEast), dot(d, uNearTileNorth)) * k;
  }

  // центр тексела i ↔ (i + 0.5)/texels
  vec2 terrainNearTileUv(vec2 xy) {
    return xy / (uNearTileTexels * uNearTileTexelMeters) + 0.5;
  }

  // высота над сферой относительно центра плитки, метры
  float terrainNearTileHeight(vec2 xy) {
    return texture2DLodEXT(uNearTile, terrainNearTileUv(xy), 0.0).r;
  }

  // 1 внутри 0.8·half, 0 на краю плитки, по max(|x|, |y|)
  float terrainNearEdgeWeight(vec2 xy) {
    float halfMeters = 0.5 * uNearTileTexels * uNearTileTexelMeters;
    return 1.0 - smoothstep(0.8 * halfMeters, halfMeters, max(abs(xy.x), abs(xy.y)));
  }

  // вес ближнего слоя во фрагменте; uNearTileWeight уже несёт высоту камеры и силу ручки
  float terrainNearShadowWeight(vec3 dir) {
    // задняя полусфера: проекция не определена
    if (dot(dir, uNearTileCenter) <= 0.0) return 0.0;
    return uNearTileWeight * terrainNearEdgeWeight(terrainNearTileXY(dir));
  }

  // 1 — освещено, 0 — в тени; dir — радиаль фрагмента, sunLocal — единичное НА солнце.
  // Без раннего выхода по солнцу под горизонтом — тень даёт сам марш
  float terrainNearShadowMarch(vec3 dir, vec3 sunLocal) {
    float se = dot(sunLocal, uNearTileEast);
    float sn = dot(sunLocal, uNearTileNorth);
    float horiz = length(vec2(se, sn));
    // солнце в зените (по базису центра плитки): направления по плитке нет
    if (horiz < 1e-6) return 1.0;
    vec2 stepDir = vec2(se, sn) / horiz;

    float sinT = dot(sunLocal, dir);
    float tanT = sinT / max(sqrt(max(1.0 - sinT * sinT, 0.0)), 1e-6);
    float R = uBodyRadiusMeters;
    vec2 p0 = terrainNearTileXY(dir);
    float h0 = terrainNearTileHeight(p0);

    float bias = uNearTileTexelMeters * TERRAIN_NEAR_SHADOW_BIAS_SLOPE;
    float sMin = uNearTileTexelMeters;
    float sMax = max(uNearShadowMaxDistMeters, sMin * 2.0);
    float ratio = pow(sMax / sMin, 1.0 / float(TERRAIN_NEAR_SHADOW_STEPS - 1));
    float s = sMin;
    float occl = 0.0;

    for (int i = 0; i < TERRAIN_NEAR_SHADOW_STEPS; i++) {
      // кривизна ПЛЮС: сфера уходит из-под прямой
      float hRay = h0 + s * tanT + s * s / (2.0 * R);
      float pen = (terrainNearTileHeight(p0 + stepDir * s) - hRay - bias) / max(s * uShadowPenumbraTan, 1e-6);
      occl = max(occl, clamp(pen, 0.0, 1.0));
      if (occl >= 1.0) break;
      s *= ratio;
    }

    return 1.0 - occl;
  }

    #endif

    #ifdef USE_SUN_TINT

  const int ATMO_TRANSMITTANCE_W = 256;
  const int ATMO_TRANSMITTANCE_H = 64;

  float atmoSafeSqrt(float a) { return sqrt(max(a, 0.0)); }

  float atmoUnitToTexCoord(float x, int n) {
    return 0.5 / float(n) + x * (1.0 - 1.0 / float(n));
  }

  float atmoDistanceToTop(float r, float mu) {
    float discriminant = r * r * (mu * mu - 1.0) + uAtmoTopRadius * uAtmoTopRadius;
    return max(-r * mu + atmoSafeSqrt(discriminant), 0.0);
  }

  vec2 atmoTransmittanceUv(float r, float mu) {
    float H = sqrt(uAtmoTopRadius * uAtmoTopRadius - uAtmoBottomRadius * uAtmoBottomRadius);
    float rho = atmoSafeSqrt(r * r - uAtmoBottomRadius * uAtmoBottomRadius);
    float d = atmoDistanceToTop(r, mu);
    float d_min = uAtmoTopRadius - r;
    float d_max = rho + H;
    float x_mu = (d - d_min) / (d_max - d_min);
    // Ниже горизонта d выходит за d_max (x_mu > 1) — кламп к [0,1] = ClampToEdge
    // самой LUT; smoothstep солнечного диска там и так даёт 0.
    x_mu = clamp(x_mu, 0.0, 1.0);
    float x_r = rho / H;
    return vec2(atmoUnitToTexCoord(x_mu, ATMO_TRANSMITTANCE_W), atmoUnitToTexCoord(x_r, ATMO_TRANSMITTANCE_H));
  }

  vec3 atmoTransmittanceToTop(float r, float mu) {
    return texture2D(uAtmoTransmittance, atmoTransmittanceUv(r, mu)).rgb;
  }

  vec3 atmoTransmittanceToSun(float r, float muS) {
    float sin_theta_h = uAtmoBottomRadius / r;
    float cos_theta_h = -sqrt(max(1.0 - sin_theta_h * sin_theta_h, 0.0));
    return atmoTransmittanceToTop(r, muS) *
      smoothstep(-sin_theta_h * uAtmoSunAngularRadius, sin_theta_h * uAtmoSunAngularRadius, muS - cos_theta_h);
  }

  // tint = T(r, muS) / T(r, 1) на радиусе r (км): в зените 1, к терминатору теплее и темнее, как небо
  vec3 sunTintAt(float r, float muS) {
    vec3 zenith = max(atmoTransmittanceToSun(r, 1.0), vec3(1e-3));
    return clamp(atmoTransmittanceToSun(r, muS) / zenith, 0.0, 1.0);
  }

  // палуба и вода — на радиусе датума
  vec3 sunTint(float muS) {
    return sunTintAt(uAtmoDatumRadius, muS);
  }

  const int ATMO_IRRADIANCE_W = 64;
  const int ATMO_IRRADIANCE_H = 16;

  // Порт GetIrradianceTextureUvFromRMuS: x = μ_s·0.5+0.5, y = (r − bottom)/(top − bottom)
  vec2 atmoIrradianceUv(float r, float muS) {
    float xR = clamp((r - uAtmoBottomRadius) / (uAtmoTopRadius - uAtmoBottomRadius), 0.0, 1.0);
    float xMuS = muS * 0.5 + 0.5;
    return vec2(atmoUnitToTexCoord(xMuS, ATMO_IRRADIANCE_W), atmoUnitToTexCoord(xR, ATMO_IRRADIANCE_H));
  }

  // Небо в тени: E_sky(датум, μ_s), нормированная люмой зенитного значения — в зените люма ≡ 1
  // (яркость пола не меняется, только цвет), к терминатору спад по LUT
  vec3 skyAmbientTint(float muS) {
    vec3 e = texture2D(uAtmoIrradiance, atmoIrradianceUv(uAtmoDatumRadius, muS)).rgb;
    vec3 zenith = texture2D(uAtmoIrradiance, atmoIrradianceUv(uAtmoDatumRadius, 1.0)).rgb;
    float lum = max(dot(zenith, vec3(0.2126, 0.7152, 0.0722)), 1e-4);
    return clamp(e / lum, 0.0, 4.0);
  }

    #endif

    // Облачный слой на высоте h: параллакс, утолщение у края, свет слоя, тень (чанк CloudLayer)
    #ifdef USE_CLOUD

  uniform float uCloudHeightUnits;
  uniform float uCloudHeightKm;
  uniform float uCloudLightSoftness;
  uniform float uCloudShadowStrength;


  #define CLOUD_SLANT_MIN_MU 0.1
  #define CLOUD_SLANT_GATE_LO 0.05
  #define CLOUD_SLANT_GATE_HI 0.15
  #define CLOUD_SHADOW_MIN_COS 0.15

  // Точка слоя на луче взгляда: от P = R·d назад к камере до сферы R + h.
  // Камера ниже слоя не обрабатывается: там слой погашен высотным fade (uCloudOpacity).
  vec3 cloudLayerPoint(vec3 dirLocal, vec3 viewLocal) {
    if (uCloudHeightUnits <= 0.0) return dirLocal;
    float R = uBodyRadiusUnits;
    float h = uCloudHeightUnits;
    vec3 P = dirLocal * R;
    float b = dot(P, viewLocal);
    // разность квадратов радиусов — h·(2R + h): (R + h)² − R² в float32 теряет точность при h ≪ R
    float t = b + sqrt(max(b * b + h * (2.0 * R + h), 0.0));
    return normalize(P - t * viewLocal);
  }

  // Утолщение у края: путь сквозь слой ∝ 1/μ; 0 и 1 — неподвижные точки (пусто — прозрачно)
  float cloudSlantAlpha(float alpha, float muV) {
    return 1.0 - pow(max(1.0 - alpha, 0.0), 1.0 / max(muV, CLOUD_SLANT_MIN_MU));
  }

  // Свет в точке слоя: облако на высоте видит солнце дольше земли (dip), плюс мягкость рассеяния
  float cloudSunLight(vec3 cloudDir, vec3 sunLocal) {
    float R = uBodyRadiusUnits;
    float h = max(uCloudHeightUnits, 0.0);
    float dip = sqrt(h * (2.0 * R + h)) / (R + h);
    float k = dip + uCloudLightSoftness;
    return clamp((dot(cloudDir, sunLocal) + k) / (1.0 + k), 0.0, 1.0);
  }

  // Слой в пикселе: премультиплированный альбедо и покрытие с утолщением — оба уже с высотным fade
  void cloudLayerSample(vec3 dirLocal, vec3 viewLocal, out vec3 cloudPremul, out float cloudAlphaSlant, out vec3 cloudDir) {
    cloudDir = cloudLayerPoint(dirLocal, viewLocal);
    vec3 cloudTex = texture2D(cloudMap, terrainUv(cloudDir)).rgb;
    // покрытие — свойство текстуры, не освещения
    float alpha = pow(dot(cloudTex, vec3(1.0)) / 3.0, 0.5);
    vec3 albedo = min(cloudTex / max(alpha, 1e-4), vec3(1.0));
    float muV = abs(dot(cloudDir, -viewLocal));
    // утолщение только у настоящих облаков: шум JPEG в пустом небе (α ≲ 0.05) у лимба дал бы тёмное кольцо
    float slantGate = smoothstep(CLOUD_SLANT_GATE_LO, CLOUD_SLANT_GATE_HI, alpha);
    cloudAlphaSlant = mix(alpha, cloudSlantAlpha(alpha, muV), slantGate) * uCloudOpacity;
    cloudPremul = albedo * cloudAlphaSlant;
  }

  // Радиация облака: альбедо × свет слоя × солнце на высоте облака × цвет звезды.
  // Под USE_SUN_TINT световой хвост за геометрическим горизонтом (−dip) срезается горизонтом пропускания,
  // поэтому cloudLightSoftness виден полностью только на телах без солнечного тинта.
  vec3 cloudLitRadiance(vec3 cloudPremul, vec3 cloudDir, vec3 sunLocal) {
    vec3 radiance = cloudPremul * cloudSunLight(cloudDir, sunLocal);
    #ifdef USE_SUN_TINT
      radiance *= mix(vec3(1.0), sunTintAt(uAtmoDatumRadius + uCloudHeightKm, dot(cloudDir, sunLocal)), uSunTintStrength);
    #endif
    #ifdef USE_LIGHT_TINT
      radiance *= uLightColor;
    #endif
    return radiance;
  }

  // Тень облаков на поверхности: облако, затеняющее точку, стоит по направлению к солнцу
  // на h·tan θ (θ — зенитный угол); только прямой свет. muS = dot(dirLocal, sunLocal)
  float cloudShadowAt(vec3 dirLocal, vec3 sunLocal, float muS) {
    vec3 eastLocal = cross(vec3(0.0, 1.0, 0.0), dirLocal);
    vec2 uv = terrainUv(dirLocal);
    vec3 sunTangent = sunLocal - dirLocal * muS;
    float cosZ = max(muS, CLOUD_SHADOW_MIN_COS);
    vec3 offsetUnits = sunTangent / cosZ * uCloudHeightUnits;
    // eastLocal = cross(up, dir): длина = cos φ; north = cross(dir, east)
    float cosLat = max(length(eastLocal), 1e-3);
    vec3 eastUnit = eastLocal / cosLat;
    vec3 northUnit = normalize(cross(dirLocal, eastUnit));
    vec2 uvShadow = uv + vec2(dot(offsetUnits, eastUnit) / (6.2831853 * uBodyRadiusUnits * cosLat),
                              dot(offsetUnits, northUnit) / (3.1415927 * uBodyRadiusUnits));
    vec3 cloudAtShadow = texture2D(cloudMap, uvShadow).rgb;
    // × uCloudOpacity: тень гаснет с высотой камеры вместе с самим слоем — не баг
    float alphaShadow = pow(dot(cloudAtShadow, vec3(1.0)) / 3.0, 0.5) * uCloudOpacity;
    // ровно в полюсе eastLocal = 0 → базис вырожден: тень гасится, NaN не рождается
    return 1.0 - uCloudShadowStrength * alphaShadow * smoothstep(0.0, 0.2, muS) * step(1e-4, length(eastLocal));
  }

    #endif

    // Закон реголита безатмосферных тел (Lommel–Seeliger + оппозиционный всплеск) — функция чанка AsteroidBrdf
    #ifdef USE_REGOLITH
      uniform float uRegolithMix;
      uniform float uOppositionSurge;

  // Диффуз реголита: NdotL/NdotV — косинусы к свету и к камере, cosPhase = dot(L, V)
  float asteroidRegolithDiffuse(float NdotL, float NdotV, float cosPhase, float lunarMix, float surge) {
    float nl = max(NdotL, 0.0);
    float nv = max(NdotV, 0.0);
    float lambert = nl;
    float lommel = 2.0 * nl / max(nl + nv, 1e-4);
    float diffuse = mix(lambert, lommel, lunarMix);
    float g = acos(clamp(cosPhase, -1.0, 1.0));
    float opposition = 1.0 + surge * exp(-g / 0.1);
    return diffuse * opposition;
  }

  // Planetshine: N и dirPlanet — в одном пространстве (view), ringPos и
  // lightDirRing — в ring-local (планета в начале координат), planetRadius —
  // в единицах ringPos. Возвращает множитель альбедо
  float asteroidPlanetshine(vec3 N, vec3 dirPlanet, vec3 ringPos, vec3 lightDirRing, float planetRadius) {
    float d = length(ringPos);
    if (planetRadius <= 0.0 || d <= planetRadius) return 0.0;
    vec3 pHat = ringPos / d;
    float phase = 0.5 * (1.0 + dot(pHat, lightDirRing));
    float angR = planetRadius / d;
    float solid = angR * angR;
    float wrap = angR;
    float wrapped = max(dot(N, dirPlanet) + wrap, 0.0) / (1.0 + wrap);
    return phase * solid * wrapped;
  }

    #endif

    #ifdef USE_TERRAIN_DETAIL
      varying vec3 vDetailPos;
      varying vec3 vDetailPos2;

  uniform sampler2D uDetailDiffMap;
  uniform sampler2D uDetailNorMap;
  uniform sampler2D uDetailArmMap;
  uniform sampler2D uDetailNor2Map;
  uniform float uDetailScale;
  uniform float uDetailScale2;
  uniform float uDetailNormalScale;
  uniform float uDetailSaturation;
  uniform float uDetailBrightness;
  uniform float uDetailAoInfluence;
  uniform vec3 uDetailLayerGates;
  uniform vec4 uDetailFadeRange;
  // Нормировка набора к его средним (detailTextureStats.ts): x = 1/meanLum
  // диффуза, y = 1/meanAo ARM. Без неё деталь умножала альбедо на среднюю
  // яркость файла (rocky ≈ 0.23) и тело темнело по мере вхождения слоя.
  uniform vec2 uDetailTintNorm;
  uniform vec2 uSteepTintNorm;
  uniform sampler2D uSteepNorMap;
  uniform sampler2D uSteepArmMap;
  uniform sampler2D uSteepDiffMap;
  // 0/1 по факту наличия всех трёх steep-карт И несовпадения с родным
  // набором (rocky-тела — вырожденный бленд, гейт держит Task 3 на CPU).
  uniform float uSteepGate;
  // x = steepStart, y = steepFull, z = steepBreakup — tan-единицы уклона
  // (см. докстроку чанка, раздел «ЗОНЫ МАТЕРИАЛА»; резолвит Task 3).
  uniform vec3 uSteepMask;
  // Цвет каменной зоны — множитель tintSteep (обе ветки: чистый steep и
  // полоса перехода), после нормировки к среднему (uSteepTintNorm) и ПОСЛЕ
  // насыщенности/яркости общих ручек детали (они внутри sampleDetailSet).
  uniform vec3 uSteepTint;


  // Веса проекций: степень 4 прижимает бленд к доминирующей оси — меньше
  // «двоения» текстуры на диагональных нормалях
  vec3 triplanarWeights(vec3 objNormal) {
    vec3 w = pow(abs(objNormal), vec3(4.0));
    return w / (w.x + w.y + w.z);
  }

  // Ядро бленда albedo/ARM: одинаковая математика для обеих карт (взвешенная
  // сумма трёх проекций), поэтому одна функция на двоих — вызывающая сторона
  // сама решает, что читать (albedo или ARM).
  vec3 triplanarBlendRgb(vec3 cx, vec3 cy, vec3 cz, vec3 w) {
    return cx * w.x + cy * w.y + cz * w.z;
  }

  // Whiteout-бленд нормалей: тангенциальные компоненты суммируются с геом.
  // нормалью по осям проекции, z-компоненты перемножаются — швов между
  // проекциями нет, «плоского» усреднения тоже. tx/ty/tz — уже распакованные
  // ([-1,1]) значения проекций, выбор способа их получить (обычная выборка
  // или стохастическая) — забота вызывающей стороны.
  vec3 triplanarBlendNormal(vec3 tx, vec3 ty, vec3 tz, vec3 n, vec3 w) {
    tx = vec3(tx.xy + n.zy, abs(tx.z) * n.x);
    ty = vec3(ty.xy + n.xz, abs(ty.z) * n.y);
    tz = vec3(tz.xy + n.xy, abs(tz.z) * n.z);
    return normalize(tx.zyx * w.x + ty.xzy * w.y + tz.xyz * w.z);
  }

  vec3 triplanarAlbedo(sampler2D map, vec3 p, vec3 w, vec2 offset) {
    vec3 cx = texture2D(map, p.zy * uDetailScale + offset).rgb;
    vec3 cy = texture2D(map, p.xz * uDetailScale + offset).rgb;
    vec3 cz = texture2D(map, p.xy * uDetailScale + offset).rgb;
    return triplanarBlendRgb(cx, cy, cz, w);
  }

  vec3 triplanarArm(sampler2D map, vec3 p, vec3 w, vec2 offset) {
    vec3 ax = texture2D(map, p.zy * uDetailScale + offset).rgb;
    vec3 ay = texture2D(map, p.xz * uDetailScale + offset).rgb;
    vec3 az = texture2D(map, p.xy * uDetailScale + offset).rgb;
    return triplanarBlendRgb(ax, ay, az, w);
  }

  vec3 triplanarNormal(sampler2D map, vec3 p, vec3 n, vec3 w, vec2 offset) {
    vec3 tx = texture2D(map, p.zy * uDetailScale + offset).xyz * 2.0 - 1.0;
    vec3 ty = texture2D(map, p.xz * uDetailScale + offset).xyz * 2.0 - 1.0;
    vec3 tz = texture2D(map, p.xy * uDetailScale + offset).xyz * 2.0 - 1.0;
    return triplanarBlendNormal(tx, ty, tz, n, w);
  }


  // Полуширина ветвления маски зон (см. докстроку чанка, «ЗОНЫ МАТЕРИАЛА»):
  // < EPS/> 1-EPS читает один набор, между ними — оба.
  #define STEEP_EPS 0.003

  // Скалярный/векторный хеш — от КВАНТОВАННОЙ величины на вызове (floor(p)
  // передаёт вызывающая сторона), не от сырого варьинга.
  float hash21(vec2 p) {
    return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
  }

  vec2 hash22(vec2 p) {
    vec2 h = vec2(
      dot(p, vec2(127.1, 311.7)),
      dot(p, vec2(269.5, 183.3))
    );
    return fract(sin(h) * 43758.5453);
  }

  // Value noise — непрерывная скалярная функция без текстур: билинейный mix
  // хешей четырёх углов ячейки floor(p) по Hermite-сглаженной дробной части.
  // Нужна как НЕПРЕРЫВНЫЙ индекс варианта для sampleDetiled — см. её докстроку.
  // Решётка хеша — по модулю 256 ячеек: p приходит из детального домена
  // (detailPos*scale, ячейка 4 тайла из-за множителя 0.25 в applyTerrainDetail)
  // — 256×4 = 1024 = WRAP_TILES (detailWrap.ts), поэтому шов обёртки k·W
  // домена невидим для vnoise. Сосед сворачивается ОТДЕЛЬНО от базовой ячейки
  // (i1 = mod(i + 1.0, 256.0)), а не как (i + 1) от уже свёрнутого i — иначе
  // правый угол ячейки 255 хешируется от 256, а левый угол ячейки 0 (тот же
  // физический угол решётки) — от 0: разные хеши одной точки дают разрыв l
  // на каждой границе периода.
  float vnoise(vec2 p) {
    vec2 i = floor(p);
    vec2 f = fract(p);
    vec2 i0 = mod(i, 256.0);
    vec2 i1 = mod(i + 1.0, 256.0);
    float a = hash21(i0);
    float b = hash21(vec2(i1.x, i0.y));
    float c = hash21(vec2(i0.x, i1.y));
    float d = hash21(i1);
    vec2 u = f * f * (3.0 - 2.0 * f);
    return mix(mix(a, b, u.x), mix(c, d, u.x), u.y);
  }

  // Стохастическая детайлизация одной карты — непрерывный 2-тап (IQ «texture
  // repetition» technique 3 / Suslik): вариант выбирается НЕ ячейкой самого
  // uv (та схема разрывна на каждой границе ячейки текстуры), а
  // floor(l)/fract(l) НЕПРЕРЫВНОГО индекса l (см. вызывающую сторону —
  // applyTerrainDetail считает l = 8·vnoise(0.25·uv) один раз на ось). floor(l)
  // меняется РОВНО там, где fract(l) проходит через 0 — в этой точке вес b
  // уже полностью переключён на входящий вариант (offB текущего интервала ==
  // offA следующего, оба — hash22 одного и того же floor(l)+1), поэтому
  // результат непрерывен по построению. Производные (ddx/ddy) — от ИСХОДНОГО
  // uv, посчитаны вызывающей стороной ДО стохастического сдвига offA/offB —
  // иначе выбор мипа скачет вместе со сдвигом и на переходах виден шов.
  vec4 sampleDetiled(sampler2D map, vec2 uv, vec2 ddx, vec2 ddy, float l) {
    float ia = floor(l);
    float f = fract(l);
    vec2 offA = hash22(vec2(ia, 3.0));
    vec2 offB = hash22(vec2(ia + 1.0, 3.0));
    float b = smoothstep(0.2, 0.8, f);
    vec4 colA = texture2DGradEXT(map, uv + offA, ddx, ddy);
    vec4 colB = texture2DGradEXT(map, uv + offB, ddx, ddy);
    return mix(colA, colB, b);
  }

  // Группа uv + производные для трёх планарных проекций (zy/xz/xy) ОДНОГО
  // домена (p*scale). Вычисляется в triplanarUvFor ниже — ОДИН раз, в
  // однородном потоке, до любых ветвлений по fade/маске (см. докстроку
  // чанка) — dFdx/dFdy под дивергентным потоком формально UB, а маска зон
  // ветвится на пиксельной частоте, где UB был видимым (мип-волоски).
  struct TriplanarUv {
    vec2 zy; vec2 zyDx; vec2 zyDy;
    vec2 xz; vec2 xzDx; vec2 xzDy;
    vec2 xy; vec2 xyDx; vec2 xyDy;
  };

  TriplanarUv triplanarUvFor(vec3 p, float scale) {
    TriplanarUv t;
    t.zy = p.zy * scale;
    t.xz = p.xz * scale;
    t.xy = p.xy * scale;
    t.zyDx = dFdx(t.zy);
    t.zyDy = dFdy(t.zy);
    t.xzDx = dFdx(t.xz);
    t.xzDy = dFdy(t.xz);
    t.xyDx = dFdx(t.xy);
    t.xyDy = dFdy(t.xy);
    return t;
  }

  // Стохастические обёртки террейна: те же 3 планарные проекции, что и
  // классические triplanarAlbedo/Arm/Normal, но каждая читается через
  // sampleDetiled вместо прямой выборки. l — общий индекс на ось (см.
  // докстроку чанка), делится всеми четырьмя картами и обеими шкалами.
  // uv+производные приходят готовыми (TriplanarUv, см. выше) — обёртки сами
  // больше не считают dFdx/dFdy, только читают текстуру. Один и тот же t
  // обслуживает оба набора крупной шкалы (родной/steep — зона меняет
  // ТЕКСТУРЫ, не домен адресации) и, с другим t (от detailPos2/uDetailScale2),
  // мелкую шкалу — функции переиспользуются без копирования бленда. Бленд
  // трёх проекций — ОБЩЕЕ ядро из чанка TriplanarDetail (triplanarBlendRgb/
  // Normal), не копия.
  vec3 triplanarAlbedoDetiled(sampler2D map, TriplanarUv t, vec3 w, vec3 l) {
    vec3 cx = sampleDetiled(map, t.zy, t.zyDx, t.zyDy, l.x).rgb;
    vec3 cy = sampleDetiled(map, t.xz, t.xzDx, t.xzDy, l.y).rgb;
    vec3 cz = sampleDetiled(map, t.xy, t.xyDx, t.xyDy, l.z).rgb;
    return triplanarBlendRgb(cx, cy, cz, w);
  }

  vec3 triplanarArmDetiled(sampler2D map, TriplanarUv t, vec3 w, vec3 l) {
    vec3 ax = sampleDetiled(map, t.zy, t.zyDx, t.zyDy, l.x).rgb;
    vec3 ay = sampleDetiled(map, t.xz, t.xzDx, t.xzDy, l.y).rgb;
    vec3 az = sampleDetiled(map, t.xy, t.xyDx, t.xyDy, l.z).rgb;
    return triplanarBlendRgb(ax, ay, az, w);
  }

  vec3 triplanarNormalDetiled(sampler2D map, TriplanarUv t, vec3 n, vec3 w, vec3 l) {
    vec3 tx = sampleDetiled(map, t.zy, t.zyDx, t.zyDy, l.x).xyz * 2.0 - 1.0;
    vec3 ty = sampleDetiled(map, t.xz, t.xzDx, t.xzDy, l.y).xyz * 2.0 - 1.0;
    vec3 tz = sampleDetiled(map, t.xy, t.xyDx, t.xyDy, l.z).xyz * 2.0 - 1.0;
    return triplanarBlendNormal(tx, ty, tz, n, w);
  }

  // Общее чтение тройки (нормаль/AO/tint-diffuse) для ОДНОГО набора крупной
  // шкалы (родного или steep) — тело идентично прежнему коду ветки fade1,
  // параметризовано сэмплерами набора. Гейты AO/diffuse — те же
  // uDetailLayerGates.x/y, общие на оба набора (свойство слоя, не зоны).
  // t/w/l не параметризованы по зоне — зона не меняет домен адресации (см.
  // докстроку чанка, «ЗОНЫ МАТЕРИАЛА»), только сами карты. t — готовый
  // TriplanarUv, посчитанный ДО ветвления по маске (см. applyTerrainDetail) —
  // сама функция dFdx/dFdy не считает.
  void sampleDetailSet(
    sampler2D nor, sampler2D arm, sampler2D diff, vec2 norm, TriplanarUv t, vec3 w, vec3 l, vec3 nLocal,
    out vec3 nOut, out float aoOut, out vec3 tintOut, out float roughnessOut
  ) {
    nOut = triplanarNormalDetiled(nor, t, nLocal, w, l);

    // AO и шероховатость — один сэмпл ARM (R/G каналы): AO относительно
    // СВОЕГО среднего (norm.y), модуляция ±, кламп 2 — гард от битой
    // статистики; канал G — шероховатость, сырое [0,1] (R — AO, B — металл),
    // читает блеск льда хоста.
    aoOut = 1.0;
    roughnessOut = 1.0;
    if (uDetailLayerGates.x > 0.0) {
      vec3 armSample = triplanarArmDetiled(arm, t, w, l);
      aoOut = mix(1.0, clamp(armSample.r * norm.y, 0.0, 2.0), uDetailAoInfluence);
      roughnessOut = clamp(armSample.g, 0.0, 1.0);
    }

    // Диффуз тоже нормирован к своему среднему (norm.x, среднее слоя = 1).
    tintOut = vec3(1.0);
    if (uDetailLayerGates.y > 0.0) {
      vec3 diffuseDetail = clamp(triplanarAlbedoDetiled(diff, t, w, l) * norm.x, 0.0, 2.0);
      float lum = dot(diffuseDetail, vec3(0.2126, 0.7152, 0.0722));
      tintOut = mix(vec3(lum), diffuseDetail, uDetailSaturation) * uDetailBrightness;
    }
  }

  void applyTerrainDetail(inout vec3 nLocal, inout vec3 albedoMul, inout float occlusion, vec3 detailPos, vec3 detailPos2, float viewDistance, float slopeTan, inout float roughness) {
    // Пороги фейда — ручки пер-тела в метрах дистанции, сконвертированные
    // в юниты на CPU (см. докстрока чанка и PlanetShader.uDetailFadeRange).
    float fade1 = 1.0 - smoothstep(uDetailFadeRange.x, uDetailFadeRange.y, viewDistance);
    float fade2 = uDetailLayerGates.z * (1.0 - smoothstep(uDetailFadeRange.z, uDetailFadeRange.w, viewDistance));

    if (max(fade1, fade2) > 0.0) {
      // Веса трипланара — от нормали после slope-карты и полосы (до
      // наклона деталью), не от домена адресации карт: на стенах проекция
      // сверху (по dirLocal) растягивала деталь 1.4–2.2× — nLocal
      // мип-фильтрована, веса непрерывны.
      vec3 w = triplanarWeights(nLocal);

      // Непрерывный индекс варианта — один раз на проекционную ось, делится
      // всеми четырьмя картами обеих шкал (см. «Экономика» в докстроке чанка).
      // Домен — detailPos (крупная шкала); ячейка vnoise — 4 тайла (0.25),
      // решётка хеша mod 256 — вместе 1024 = WRAP_TILES, шов k·W не виден.
      vec3 l = vec3(
        8.0 * vnoise(0.25 * (detailPos.zy * uDetailScale)),
        8.0 * vnoise(0.25 * (detailPos.xz * uDetailScale)),
        8.0 * vnoise(0.25 * (detailPos.xy * uDetailScale))
      );

      // Текстурные градиенты — здесь, СРАЗУ после w/l, в однородном потоке:
      // ДО ветки по маске зон (пиксельная частота ветвления — там UB dFdx
      // под дивергентным потоком был ВИДИМ, мип-волоски вдоль изоконтуров
      // m = STEEP_EPS/1-EPS) и ДО fade1/fade2 (там UB почти безвреден, но
      // выносим единообразно — см. докстроку чанка). Обе шкалы — свой домен,
      // считаются здесь безусловно, даже если соответствующий fade окажется
      // < 0 ниже (дешёвая ALU, не текстурная выборка).
      TriplanarUv uvBig = triplanarUvFor(detailPos, uDetailScale);
      TriplanarUv uvSmall = triplanarUvFor(detailPos2, uDetailScale2);

      if (fade1 > 0.0) {
        // Маска зон: камень на крутом. breakup переиспользует l.z (домен и
        // ось те же — detailPos.xy·uDetailScale, см. l выше) делением на 8
        // (обратное домножению в определении l) — ни второго vnoise, ни
        // новых текстурных выборок. uSteepGate — множитель прямо в маске
        // (рулинг): выключенный/неполный steep-набор даёт m ≡ 0 и код ниже
        // сваливается в единственную ветку m < STEEP_EPS — родной набор,
        // как до этой задачи. Без slope-карты slopeTan = 0 (см. вызывающую
        // сторону, PlanetShaderTemplate) — тот же эффект.
        float m = uSteepGate * smoothstep(uSteepMask.x, uSteepMask.y, slopeTan + uSteepMask.z * (l.z / 8.0 - 0.5));

        vec3 nNative, nSteep;
        float aoNative, aoSteep;
        vec3 tintNative, tintSteep;
        float rNative, rSteep;

        if (m < STEEP_EPS) {
          // Вне зоны — читается ровно один (родной) набор.
          sampleDetailSet(uDetailNorMap, uDetailArmMap, uDetailDiffMap, uDetailTintNorm, uvBig, w, l, nLocal, nNative, aoNative, tintNative, rNative);
          nLocal = normalize(nLocal + uDetailNormalScale * fade1 * (nNative - nLocal));
          occlusion *= mix(1.0, aoNative, fade1);
          albedoMul *= mix(vec3(1.0), tintNative, fade1);
          roughness = mix(1.0, rNative, fade1);
        } else if (m > 1.0 - STEEP_EPS) {
          // Только steep — симметрично ветке выше.
          sampleDetailSet(uSteepNorMap, uSteepArmMap, uSteepDiffMap, uSteepTintNorm, uvBig, w, l, nLocal, nSteep, aoSteep, tintSteep, rSteep);
          tintSteep *= uSteepTint;
          nLocal = normalize(nLocal + uDetailNormalScale * fade1 * (nSteep - nLocal));
          occlusion *= mix(1.0, aoSteep, fade1);
          albedoMul *= mix(vec3(1.0), tintSteep, fade1);
          roughness = mix(1.0, rSteep, fade1);
        } else {
          // Полоса перехода: оба набора (бюджет — см. докстроку чанка).
          // Нормали — whiteout, последовательно родной вес (1-m), затем
          // steep вес m (тот же паттерн, что крупная/мелкая шкала ниже).
          // AO/tint/шероховатость — не направления, обычный mix(a, b, m).
          sampleDetailSet(uDetailNorMap, uDetailArmMap, uDetailDiffMap, uDetailTintNorm, uvBig, w, l, nLocal, nNative, aoNative, tintNative, rNative);
          nLocal = normalize(nLocal + uDetailNormalScale * fade1 * (1.0 - m) * (nNative - nLocal));

          sampleDetailSet(uSteepNorMap, uSteepArmMap, uSteepDiffMap, uSteepTintNorm, uvBig, w, l, nLocal, nSteep, aoSteep, tintSteep, rSteep);
          tintSteep *= uSteepTint;
          nLocal = normalize(nLocal + uDetailNormalScale * fade1 * m * (nSteep - nLocal));

          occlusion *= mix(1.0, mix(aoNative, aoSteep, m), fade1);
          albedoMul *= mix(vec3(1.0), mix(tintNative, tintSteep, m), fade1);
          roughness = mix(1.0, mix(rNative, rSteep, m), fade1);
        }
      }

      if (fade2 > 0.0) {
        // Своя точная позиция мелкого слоя (detailPos2, W2 ≠ W1) — не ratio
        // от крупной, свой TriplanarUv (uvSmall, посчитан выше вместе с
        // uvBig). l переиспользован из крупной шкалы (см. докстроку чанка) —
        // своего vnoise для мелкой шкалы нет.
        vec3 nDetail2 = triplanarNormalDetiled(uDetailNor2Map, uvSmall, nLocal, w, l);
        nLocal = normalize(nLocal + uDetailNormalScale * fade2 * (nDetail2 - nLocal));
      }
    }
  }

    #endif

    #if defined(USE_TERRAIN_MACRO_DETAIL) || defined(USE_WATER_EDGE) || defined(USE_TERRAIN_FROST)
